window.JTET_DATA = {"config":{"exam":"JTET","level":2,"title":"JTET Level 2 (Class 6 to 8)","optionsPerQuestion":4,"marking":{"correct":1,"wrong":0,"skipped":0},"fullMock":{"durationMinutes":150,"totalQuestions":150,"sectionOrder":["CDP","MATH_SCI","COMPUTER","LANG1","LANG2"]},"sectional":{"minutesPerQuestion":1},"sections":[{"id":"CDP","name":{"en":"Child Development & Pedagogy","hi":"बाल विकास एवं शिक्षाशास्त्र"},"questions":30,"marks":30,"bilingual":true,"bankFiles":["cdp.json"]},{"id":"MATH_SCI","name":{"en":"Mathematics & Science","hi":"गणित एवं विज्ञान"},"questions":50,"marks":50,"bilingual":true,"bankFiles":["maths-science.json"]},{"id":"COMPUTER","name":{"en":"Computer","hi":"कंप्यूटर"},"questions":10,"marks":10,"bilingual":true,"bankFiles":["computer.json"]},{"id":"LANG1","name":{"en":"Language-1 (English / Hindi)","hi":"भाषा-1 (अंग्रेज़ी / हिन्दी)"},"questions":30,"marks":30,"bilingual":false,"choices":{"EN":{"name":"English","bankFiles":["english.json"]},"HI":{"name":"Hindi","bankFiles":["hindi.json"]}}},{"id":"LANG2","name":{"en":"Language-2 (Khortha)","hi":"भाषा-2 (खोरठा)"},"questions":30,"marks":30,"bilingual":false,"bankFiles":["khortha.json"]}],"cutoffs":{"GENERAL":60,"RESERVED":55},"timerWarningsMinutes":[10,5],"timerRedZoneMinutes":5},"questions":{"CDP-0001":{"id":"CDP-0001","section":"CDP","language":null,"topic":"Piaget","question":{"en":"According to Piaget, children of Class 6–8 (age 11+) are usually in which stage of cognitive development?","hi":"पियाजे के अनुसार कक्षा 6–8 (आयु 11+) के बच्चे सामान्यतः संज्ञानात्मक विकास की किस अवस्था में होते हैं?"},"options":[{"key":"A","en":"Sensorimotor","hi":"संवेदी-गामक"},{"key":"B","en":"Pre-operational","hi":"पूर्व-संक्रियात्मक"},{"key":"C","en":"Concrete operational","hi":"मूर्त संक्रियात्मक"},{"key":"D","en":"Formal operational","hi":"औपचारिक संक्रियात्मक"}],"answer":"D","explanation":{"en":"Piaget's stages: Sensorimotor (0–2), Pre-operational (2–7), Concrete operational (7–11), Formal operational (11 onwards). From about 11 years children begin abstract and hypothetical reasoning, so D is correct.","hi":"पियाजे की अवस्थाएँ: संवेदी-गामक (0–2), पूर्व-संक्रियात्मक (2–7), मूर्त संक्रियात्मक (7–11), औपचारिक संक्रियात्मक (11 वर्ष से आगे)। लगभग 11 वर्ष से बच्चे अमूर्त व परिकल्पनात्मक चिंतन करने लगते हैं, अतः D सही है।"}},"CDP-0002":{"id":"CDP-0002","section":"CDP","language":null,"topic":"Vygotsky","question":{"en":"The 'Zone of Proximal Development' (ZPD) concept was given by:","hi":"'समीपस्थ विकास का क्षेत्र' (ZPD) की अवधारणा किसने दी?"},"options":[{"key":"A","en":"Jean Piaget","hi":"जीन पियाजे"},{"key":"B","en":"Lev Vygotsky","hi":"लेव वाइगोत्स्की"},{"key":"C","en":"B. F. Skinner","hi":"बी. एफ. स्किनर"},{"key":"D","en":"Lawrence Kohlberg","hi":"लॉरेंस कोहलबर्ग"}],"answer":"B","explanation":{"en":"Vygotsky defined ZPD as the gap between what a learner can do alone and what they can do with guidance from a more knowledgeable other. Piaget gave cognitive stages, Skinner operant conditioning, and Kohlberg moral development stages.","hi":"वाइगोत्स्की ने ZPD को वह अंतर बताया जो बच्चा स्वयं कर सकता है और जो किसी अधिक जानकार की सहायता से कर सकता है। पियाजे ने संज्ञानात्मक अवस्थाएँ, स्किनर ने क्रिया-प्रसूत अनुबंधन तथा कोहलबर्ग ने नैतिक विकास की अवस्थाएँ दीं।"}},"CDP-0003":{"id":"CDP-0003","section":"CDP","language":null,"topic":"Vygotsky","question":{"en":"A teacher gives hints and support to a student and gradually withdraws it as the student becomes capable. This is called:","hi":"शिक्षक विद्यार्थी को संकेत और सहायता देता है तथा उसके सक्षम होने पर धीरे-धीरे सहायता हटा लेता है। इसे कहते हैं:"},"options":[{"key":"A","en":"Scaffolding","hi":"पाड़ (स्कैफोल्डिंग)"},{"key":"B","en":"Assimilation","hi":"आत्मसात्करण"},{"key":"C","en":"Reinforcement","hi":"पुनर्बलन"},{"key":"D","en":"Conditioning","hi":"अनुबंधन"}],"answer":"A","explanation":{"en":"Scaffolding is temporary, adjustable support given within the ZPD and withdrawn as competence grows. Assimilation is a Piagetian process; reinforcement and conditioning are behaviourist ideas.","hi":"स्कैफोल्डिंग ZPD के भीतर दी जाने वाली अस्थायी सहायता है जो सक्षमता बढ़ने पर हटा ली जाती है। आत्मसात्करण पियाजे की अवधारणा है; पुनर्बलन व अनुबंधन व्यवहारवादी अवधारणाएँ हैं।"}},"CDP-0004":{"id":"CDP-0004","section":"CDP","language":null,"topic":"Kohlberg","question":{"en":"In Kohlberg's theory, the 'good boy – good girl' orientation belongs to which level?","hi":"कोहलबर्ग के सिद्धांत में 'अच्छा लड़का – अच्छी लड़की' अभिविन्यास किस स्तर से संबंधित है?"},"options":[{"key":"A","en":"Pre-conventional","hi":"पूर्व-परंपरागत"},{"key":"B","en":"Conventional","hi":"परंपरागत"},{"key":"C","en":"Post-conventional","hi":"उत्तर-परंपरागत"},{"key":"D","en":"Sensorimotor","hi":"संवेदी-गामक"}],"answer":"B","explanation":{"en":"The conventional level has Stage 3 (good boy–good girl / interpersonal accord) and Stage 4 (law and order). Sensorimotor is a Piaget stage, not Kohlberg's.","hi":"परंपरागत स्तर में अवस्था 3 (अच्छा लड़का–अच्छी लड़की) और अवस्था 4 (कानून व व्यवस्था) आती हैं। संवेदी-गामक पियाजे की अवस्था है, कोहलबर्ग की नहीं।"}},"CDP-0005":{"id":"CDP-0005","section":"CDP","language":null,"topic":"Growth & development","question":{"en":"Which statement about development is correct?","hi":"विकास के संबंध में कौन-सा कथन सही है?"},"options":[{"key":"A","en":"Development is discontinuous and stops at adolescence","hi":"विकास असतत है और किशोरावस्था में रुक जाता है"},{"key":"B","en":"Development proceeds from general to specific","hi":"विकास सामान्य से विशिष्ट की ओर होता है"},{"key":"C","en":"All children develop at exactly the same rate","hi":"सभी बच्चों का विकास बिल्कुल समान गति से होता है"},{"key":"D","en":"Development depends only on heredity","hi":"विकास केवल वंशानुक्रम पर निर्भर है"}],"answer":"B","explanation":{"en":"A principle of development is that it moves from general to specific responses (e.g. a baby waves the whole arm before grasping with fingers). Development is continuous, varies between individuals, and results from heredity AND environment.","hi":"विकास का एक सिद्धांत है कि यह सामान्य से विशिष्ट की ओर होता है (जैसे शिशु पहले पूरा हाथ हिलाता है, फिर उँगलियों से पकड़ता है)। विकास सतत है, व्यक्तियों में भिन्न होता है और वंशानुक्रम व वातावरण दोनों पर निर्भर है।"}},"CDP-0006":{"id":"CDP-0006","section":"CDP","language":null,"topic":"Learning theories","question":{"en":"Operant conditioning theory is associated with:","hi":"क्रिया-प्रसूत अनुबंधन सिद्धांत किससे संबंधित है?"},"options":[{"key":"A","en":"Pavlov","hi":"पावलव"},{"key":"B","en":"Thorndike","hi":"थॉर्नडाइक"},{"key":"C","en":"Skinner","hi":"स्किनर"},{"key":"D","en":"Kohler","hi":"कोहलर"}],"answer":"C","explanation":{"en":"B. F. Skinner developed operant conditioning (learning through consequences, using rats/pigeons in the Skinner box). Pavlov – classical conditioning; Thorndike – trial and error; Kohler – insight learning.","hi":"बी. एफ. स्किनर ने क्रिया-प्रसूत अनुबंधन (परिणामों द्वारा सीखना, स्किनर बॉक्स) दिया। पावलव – शास्त्रीय अनुबंधन; थॉर्नडाइक – प्रयास एवं त्रुटि; कोहलर – अंतर्दृष्टि द्वारा सीखना।"}},"CDP-0007":{"id":"CDP-0007","section":"CDP","language":null,"topic":"Inclusive education","question":{"en":"Dyslexia is primarily a difficulty related to:","hi":"डिस्लेक्सिया मुख्यतः किससे संबंधित कठिनाई है?"},"options":[{"key":"A","en":"Reading","hi":"पढ़ना"},{"key":"B","en":"Writing","hi":"लिखना"},{"key":"C","en":"Mathematical calculation","hi":"गणितीय गणना"},{"key":"D","en":"Motor coordination","hi":"गामक समन्वय"}],"answer":"A","explanation":{"en":"Dyslexia is a learning disability in reading (decoding words, spelling). Writing difficulty is dysgraphia, maths difficulty is dyscalculia, and motor coordination difficulty is dyspraxia.","hi":"डिस्लेक्सिया पढ़ने से संबंधित अधिगम अक्षमता है। लिखने की कठिनाई डिस्ग्राफिया, गणित की डिस्कैलकुलिया और गामक समन्वय की डिस्प्रैक्सिया कहलाती है।"}},"CDP-0008":{"id":"CDP-0008","section":"CDP","language":null,"topic":"RTE Act","question":{"en":"The Right of Children to Free and Compulsory Education Act, 2009 covers children of which age group?","hi":"निःशुल्क एवं अनिवार्य बाल शिक्षा का अधिकार अधिनियम, 2009 किस आयु वर्ग के बच्चों के लिए है?"},"options":[{"key":"A","en":"3 to 14 years","hi":"3 से 14 वर्ष"},{"key":"B","en":"6 to 14 years","hi":"6 से 14 वर्ष"},{"key":"C","en":"6 to 18 years","hi":"6 से 18 वर्ष"},{"key":"D","en":"5 to 15 years","hi":"5 से 15 वर्ष"}],"answer":"B","explanation":{"en":"Article 21A and the RTE Act, 2009 guarantee free and compulsory elementary education to every child aged 6 to 14 years. The Act came into force on 1 April 2010.","hi":"अनुच्छेद 21A तथा RTE अधिनियम, 2009 के अंतर्गत 6 से 14 वर्ष के प्रत्येक बच्चे को निःशुल्क एवं अनिवार्य प्रारंभिक शिक्षा का अधिकार है। यह अधिनियम 1 अप्रैल 2010 से लागू हुआ।"}},"CDP-0009":{"id":"CDP-0009","section":"CDP","language":null,"topic":"Assessment (CCE)","question":{"en":"Assessment carried out during the teaching-learning process to improve learning is called:","hi":"सीखने में सुधार के लिए शिक्षण-अधिगम प्रक्रिया के दौरान किया जाने वाला आकलन कहलाता है:"},"options":[{"key":"A","en":"Summative assessment","hi":"योगात्मक आकलन"},{"key":"B","en":"Formative assessment","hi":"रचनात्मक आकलन"},{"key":"C","en":"Placement assessment","hi":"स्थानन आकलन"},{"key":"D","en":"Terminal assessment","hi":"सत्रांत आकलन"}],"answer":"B","explanation":{"en":"Formative assessment (assessment FOR learning) happens during instruction and gives feedback to improve learning. Summative/terminal assessment happens at the end of a unit or term to grade achievement.","hi":"रचनात्मक आकलन (सीखने के लिए आकलन) शिक्षण के दौरान होता है और सुधार हेतु प्रतिपुष्टि देता है। योगात्मक/सत्रांत आकलन इकाई या सत्र के अंत में उपलब्धि मापने के लिए होता है।"}},"CDP-0010":{"id":"CDP-0010","section":"CDP","language":null,"topic":"Motivation","question":{"en":"A student solves puzzles simply because she enjoys them. This is an example of:","hi":"एक छात्रा केवल आनंद के लिए पहेलियाँ हल करती है। यह किसका उदाहरण है?"},"options":[{"key":"A","en":"Extrinsic motivation","hi":"बाह्य अभिप्रेरणा"},{"key":"B","en":"Intrinsic motivation","hi":"आंतरिक अभिप्रेरणा"},{"key":"C","en":"Negative reinforcement","hi":"नकारात्मक पुनर्बलन"},{"key":"D","en":"Punishment","hi":"दंड"}],"answer":"B","explanation":{"en":"Intrinsic motivation comes from inside — interest, curiosity or enjoyment of the task itself. Extrinsic motivation depends on outside rewards like marks, prizes or praise.","hi":"आंतरिक अभिप्रेरणा भीतर से आती है — कार्य में रुचि, जिज्ञासा या आनंद। बाह्य अभिप्रेरणा अंक, पुरस्कार या प्रशंसा जैसे बाहरी कारकों पर निर्भर होती है।"}},"COMP-0001":{"id":"COMP-0001","section":"COMPUTER","language":null,"topic":"Computer basics","question":{"en":"CPU stands for:","hi":"CPU का पूरा नाम है:"},"options":[{"key":"A","en":"Central Processing Unit","hi":"सेंट्रल प्रोसेसिंग यूनिट"},{"key":"B","en":"Central Program Unit","hi":"सेंट्रल प्रोग्राम यूनिट"},{"key":"C","en":"Computer Processing Unit","hi":"कंप्यूटर प्रोसेसिंग यूनिट"},{"key":"D","en":"Control Processing Unit","hi":"कंट्रोल प्रोसेसिंग यूनिट"}],"answer":"A","explanation":{"en":"CPU = Central Processing Unit, the 'brain' of the computer that executes instructions. It contains the ALU and the Control Unit.","hi":"CPU = सेंट्रल प्रोसेसिंग यूनिट, कंप्यूटर का 'मस्तिष्क' जो निर्देशों का निष्पादन करता है। इसमें ALU और कंट्रोल यूनिट होते हैं।"}},"COMP-0002":{"id":"COMP-0002","section":"COMPUTER","language":null,"topic":"Hardware","question":{"en":"Which of the following is an output device?","hi":"निम्नलिखित में से कौन-सा आउटपुट डिवाइस है?"},"options":[{"key":"A","en":"Keyboard","hi":"कीबोर्ड"},{"key":"B","en":"Mouse","hi":"माउस"},{"key":"C","en":"Scanner","hi":"स्कैनर"},{"key":"D","en":"Printer","hi":"प्रिंटर"}],"answer":"D","explanation":{"en":"A printer produces output (hard copy) from the computer. Keyboard, mouse and scanner send data INTO the computer, so they are input devices.","hi":"प्रिंटर कंप्यूटर से आउटपुट (हार्ड कॉपी) देता है। कीबोर्ड, माउस और स्कैनर कंप्यूटर में डेटा भेजते हैं, इसलिए ये इनपुट डिवाइस हैं।"}},"COMP-0003":{"id":"COMP-0003","section":"COMPUTER","language":null,"topic":"Memory","question":{"en":"Which memory loses its data when power is switched off?","hi":"बिजली बंद होने पर कौन-सी मेमोरी अपना डेटा खो देती है?"},"options":[{"key":"A","en":"ROM","hi":"ROM"},{"key":"B","en":"RAM","hi":"RAM"},{"key":"C","en":"Hard disk","hi":"हार्ड डिस्क"},{"key":"D","en":"Pen drive","hi":"पेन ड्राइव"}],"answer":"B","explanation":{"en":"RAM is volatile memory — its contents are erased when power is off. ROM, hard disk and pen drive are non-volatile and retain data.","hi":"RAM अस्थायी (वोलेटाइल) मेमोरी है — बिजली बंद होने पर इसका डेटा मिट जाता है। ROM, हार्ड डिस्क और पेन ड्राइव स्थायी हैं।"}},"COMP-0004":{"id":"COMP-0004","section":"COMPUTER","language":null,"topic":"Memory units","question":{"en":"1 Kilobyte (KB) is equal to:","hi":"1 किलोबाइट (KB) बराबर है:"},"options":[{"key":"A","en":"1000 bits","hi":"1000 बिट"},{"key":"B","en":"1024 bits","hi":"1024 बिट"},{"key":"C","en":"1024 bytes","hi":"1024 बाइट"},{"key":"D","en":"8 bytes","hi":"8 बाइट"}],"answer":"C","explanation":{"en":"In binary measurement, 1 KB = 2¹⁰ = 1024 bytes. Also 1 byte = 8 bits, so option D confuses byte with bit.","hi":"बाइनरी माप में 1 KB = 2¹⁰ = 1024 बाइट। साथ ही 1 बाइट = 8 बिट होते हैं।"}},"COMP-0005":{"id":"COMP-0005","section":"COMPUTER","language":null,"topic":"MS Office","question":{"en":"In MS Word, the shortcut key Ctrl + Z is used to:","hi":"MS Word में शॉर्टकट Ctrl + Z का उपयोग किसके लिए होता है?"},"options":[{"key":"A","en":"Redo","hi":"रीडू"},{"key":"B","en":"Undo","hi":"अनडू"},{"key":"C","en":"Save","hi":"सेव"},{"key":"D","en":"Zoom","hi":"ज़ूम"}],"answer":"B","explanation":{"en":"Ctrl + Z undoes the last action. Ctrl + Y is redo and Ctrl + S is save.","hi":"Ctrl + Z पिछली क्रिया को पूर्ववत (अनडू) करता है। Ctrl + Y रीडू और Ctrl + S सेव के लिए है।"}},"COMP-0006":{"id":"COMP-0006","section":"COMPUTER","language":null,"topic":"MS Office","question":{"en":"In MS Excel, which formula adds the values in cells A1 to A5?","hi":"MS Excel में सेल A1 से A5 के मानों को जोड़ने का सूत्र कौन-सा है?"},"options":[{"key":"A","en":"=ADD(A1:A5)","hi":"=ADD(A1:A5)"},{"key":"B","en":"=SUM(A1:A5)","hi":"=SUM(A1:A5)"},{"key":"C","en":"=TOTAL(A1-A5)","hi":"=TOTAL(A1-A5)"},{"key":"D","en":"SUM A1 to A5","hi":"SUM A1 to A5"}],"answer":"B","explanation":{"en":"Excel formulas start with '=' and the SUM function takes a range written with a colon: =SUM(A1:A5). ADD and TOTAL are not Excel functions for this.","hi":"Excel सूत्र '=' से शुरू होते हैं और SUM फ़ंक्शन कोलन वाली रेंज लेता है: =SUM(A1:A5)। ADD और TOTAL इसके लिए Excel फ़ंक्शन नहीं हैं।"}},"COMP-0007":{"id":"COMP-0007","section":"COMPUTER","language":null,"topic":"Internet & email","question":{"en":"In an email, 'CC' stands for:","hi":"ईमेल में 'CC' का अर्थ है:"},"options":[{"key":"A","en":"Carbon Copy","hi":"कार्बन कॉपी"},{"key":"B","en":"Computer Copy","hi":"कंप्यूटर कॉपी"},{"key":"C","en":"Common Copy","hi":"कॉमन कॉपी"},{"key":"D","en":"Closed Copy","hi":"क्लोज़्ड कॉपी"}],"answer":"A","explanation":{"en":"CC = Carbon Copy; recipients in CC are visible to everyone. BCC (Blind Carbon Copy) hides recipients from each other.","hi":"CC = कार्बन कॉपी; CC में डाले गए प्राप्तकर्ता सभी को दिखते हैं। BCC (ब्लाइंड कार्बन कॉपी) में प्राप्तकर्ता छिपे रहते हैं।"}},"COMP-0008":{"id":"COMP-0008","section":"COMPUTER","language":null,"topic":"Operating system","question":{"en":"Which of the following is an operating system?","hi":"निम्नलिखित में से कौन-सा ऑपरेटिंग सिस्टम है?"},"options":[{"key":"A","en":"MS Word","hi":"MS Word"},{"key":"B","en":"Google Chrome","hi":"गूगल क्रोम"},{"key":"C","en":"Linux","hi":"लिनक्स"},{"key":"D","en":"MS Paint","hi":"MS Paint"}],"answer":"C","explanation":{"en":"Linux is an operating system that manages hardware and runs other programs. MS Word, Chrome and Paint are application software that run on an OS.","hi":"लिनक्स एक ऑपरेटिंग सिस्टम है जो हार्डवेयर का प्रबंधन करता है। MS Word, क्रोम और Paint एप्लिकेशन सॉफ़्टवेयर हैं जो OS पर चलते हैं।"}},"COMP-0009":{"id":"COMP-0009","section":"COMPUTER","language":null,"topic":"Cyber safety","question":{"en":"A fake email that tricks users into revealing passwords or bank details is called:","hi":"पासवर्ड या बैंक विवरण निकलवाने के लिए भेजा गया नकली ईमेल कहलाता है:"},"options":[{"key":"A","en":"Spam","hi":"स्पैम"},{"key":"B","en":"Phishing","hi":"फ़िशिंग"},{"key":"C","en":"Firewall","hi":"फ़ायरवॉल"},{"key":"D","en":"Cookie","hi":"कुकी"}],"answer":"B","explanation":{"en":"Phishing pretends to be a trusted source (bank, company) to steal sensitive data. Spam is unwanted bulk mail, a firewall is a security barrier, and a cookie is small data stored by websites.","hi":"फ़िशिंग में किसी विश्वसनीय स्रोत (बैंक, कंपनी) का रूप धरकर संवेदनशील जानकारी चुराई जाती है। स्पैम अवांछित थोक मेल है, फ़ायरवॉल सुरक्षा अवरोध है, कुकी वेबसाइट द्वारा सहेजा गया छोटा डेटा है।"}},"COMP-0010":{"id":"COMP-0010","section":"COMPUTER","language":null,"topic":"ICT in education","question":{"en":"DIKSHA is a national digital platform for:","hi":"दीक्षा (DIKSHA) किसके लिए एक राष्ट्रीय डिजिटल प्लेटफ़ॉर्म है?"},"options":[{"key":"A","en":"Online banking","hi":"ऑनलाइन बैंकिंग"},{"key":"B","en":"School education and teachers","hi":"विद्यालयी शिक्षा और शिक्षक"},{"key":"C","en":"Railway booking","hi":"रेलवे बुकिंग"},{"key":"D","en":"Health records","hi":"स्वास्थ्य अभिलेख"}],"answer":"B","explanation":{"en":"DIKSHA (Digital Infrastructure for Knowledge Sharing) provides e-content, QR-coded textbooks and teacher training courses for school education.","hi":"दीक्षा (डिजिटल इन्फ्रास्ट्रक्चर फ़ॉर नॉलेज शेयरिंग) विद्यालयी शिक्षा हेतु ई-सामग्री, QR कोड वाली पाठ्यपुस्तकें और शिक्षक प्रशिक्षण पाठ्यक्रम उपलब्ध कराता है।"}},"ENG-0001":{"id":"ENG-0001","section":"LANG1","language":"EN","topic":"Grammar – Tense","question":{"en":"She ______ to school every day."},"options":[{"key":"A","en":"go"},{"key":"B","en":"goes"},{"key":"C","en":"going"},{"key":"D","en":"gone"}],"answer":"B","explanation":{"en":"'Every day' shows a habitual action, so we use the simple present tense. With a third-person singular subject (she), the verb takes -s/-es: 'goes'.","hi":"'Every day' आदतन क्रिया दर्शाता है, अतः Simple Present Tense होगा। Third person singular (she) के साथ क्रिया में -s/-es लगता है: 'goes'।"}},"ENG-0002":{"id":"ENG-0002","section":"LANG1","language":"EN","topic":"Vocabulary – Synonym","question":{"en":"Choose the synonym of 'Brave'."},"options":[{"key":"A","en":"Coward"},{"key":"B","en":"Courageous"},{"key":"C","en":"Weak"},{"key":"D","en":"Lazy"}],"answer":"B","explanation":{"en":"'Brave' means showing courage, so 'courageous' is its synonym. 'Coward' is its antonym; 'weak' and 'lazy' are unrelated in meaning.","hi":"'Brave' का अर्थ साहसी है, इसलिए 'courageous' इसका पर्यायवाची है। 'Coward' इसका विलोम है।"}},"ENG-0003":{"id":"ENG-0003","section":"LANG1","language":"EN","topic":"Vocabulary – Antonym","question":{"en":"Choose the antonym of 'Ancient'."},"options":[{"key":"A","en":"Old"},{"key":"B","en":"Historic"},{"key":"C","en":"Modern"},{"key":"D","en":"Antique"}],"answer":"C","explanation":{"en":"'Ancient' means very old; its opposite is 'modern'. Old, historic and antique are similar in meaning to ancient.","hi":"'Ancient' का अर्थ बहुत पुराना है; इसका विलोम 'modern' है। अन्य विकल्प समानार्थी हैं।"}},"ENG-0004":{"id":"ENG-0004","section":"LANG1","language":"EN","topic":"Grammar – Articles","question":{"en":"He is ______ honest man."},"options":[{"key":"A","en":"a"},{"key":"B","en":"an"},{"key":"C","en":"the"},{"key":"D","en":"no article"}],"answer":"B","explanation":{"en":"The 'h' in 'honest' is silent, so the word begins with a vowel sound /ɒ/. We use 'an' before a vowel sound.","hi":"'honest' में 'h' मूक है, अतः शब्द स्वर ध्वनि से शुरू होता है। स्वर ध्वनि से पहले 'an' आता है।"}},"ENG-0005":{"id":"ENG-0005","section":"LANG1","language":"EN","topic":"Grammar – Voice","question":{"en":"Change into passive voice: 'Ram wrote a letter.'"},"options":[{"key":"A","en":"A letter is written by Ram."},{"key":"B","en":"A letter was written by Ram."},{"key":"C","en":"A letter has been written by Ram."},{"key":"D","en":"A letter was wrote by Ram."}],"answer":"B","explanation":{"en":"Simple past active → passive: object + was/were + past participle + by + subject. So: 'A letter was written by Ram.' A is present tense, C is present perfect, D uses the wrong verb form.","hi":"Simple Past (Active) → Passive: object + was/were + V3 + by + subject। अतः 'A letter was written by Ram.'"}},"ENG-0006":{"id":"ENG-0006","section":"LANG1","language":"EN","topic":"Grammar – Prepositions","question":{"en":"The book is ______ the table."},"options":[{"key":"A","en":"on"},{"key":"B","en":"at"},{"key":"C","en":"in"},{"key":"D","en":"into"}],"answer":"A","explanation":{"en":"'On' is used for something resting on a surface. 'In' is for inside an enclosed space and 'into' shows movement.","hi":"किसी सतह के ऊपर रखी वस्तु के लिए 'on' प्रयुक्त होता है। 'in' अंदर के लिए तथा 'into' गति दर्शाने के लिए।"}},"ENG-0007":{"id":"ENG-0007","section":"LANG1","language":"EN","topic":"Language pedagogy","question":{"en":"Which approach gives the highest priority to using language for real-life communication in the classroom?"},"options":[{"key":"A","en":"Grammar-Translation Method"},{"key":"B","en":"Communicative Approach"},{"key":"C","en":"Rote memorisation"},{"key":"D","en":"Dictation method"}],"answer":"B","explanation":{"en":"The Communicative Approach focuses on meaningful interaction and real-life use of language (role plays, discussions). Grammar-Translation focuses on rules and translation; rote learning and dictation do not develop communicative ability.","hi":"Communicative Approach वास्तविक जीवन में भाषा के सार्थक प्रयोग पर बल देता है। Grammar-Translation नियमों व अनुवाद पर केंद्रित है।"}},"ENG-0008":{"id":"ENG-0008","section":"LANG1","language":"EN","topic":"Language pedagogy","question":{"en":"Reading a text quickly to get its general idea is called:"},"options":[{"key":"A","en":"Scanning"},{"key":"B","en":"Skimming"},{"key":"C","en":"Intensive reading"},{"key":"D","en":"Loud reading"}],"answer":"B","explanation":{"en":"Skimming = reading quickly for the gist/main idea. Scanning = searching quickly for specific information (a date, a name). Intensive reading is detailed, careful reading.","hi":"Skimming = मुख्य विचार हेतु तेज़ी से पढ़ना। Scanning = कोई विशेष जानकारी (तिथि, नाम) खोजना। Intensive reading = विस्तार से ध्यानपूर्वक पढ़ना।"}},"HIN-0001":{"id":"HIN-0001","section":"LANG1","language":"HI","topic":"संधि","question":{"hi":"'विद्यालय' शब्द का सही संधि-विच्छेद है:"},"options":[{"key":"A","hi":"विद्या + लय"},{"key":"B","hi":"विद्या + आलय"},{"key":"C","hi":"विद + आलय"},{"key":"D","hi":"विद्य + आलय"}],"answer":"B","explanation":{"hi":"विद्या + आलय = विद्यालय। यहाँ आ + आ = आ हुआ है, अतः यह दीर्घ स्वर संधि है।"}},"HIN-0002":{"id":"HIN-0002","section":"LANG1","language":"HI","topic":"पर्यायवाची","question":{"hi":"'सूर्य' का पर्यायवाची शब्द नहीं है:"},"options":[{"key":"A","hi":"दिनकर"},{"key":"B","hi":"भास्कर"},{"key":"C","hi":"रवि"},{"key":"D","hi":"सुधाकर"}],"answer":"D","explanation":{"hi":"दिनकर, भास्कर और रवि सूर्य के पर्यायवाची हैं। 'सुधाकर' (सुधा = अमृत की किरणें देने वाला) चंद्रमा का पर्यायवाची है।"}},"HIN-0003":{"id":"HIN-0003","section":"LANG1","language":"HI","topic":"विलोम","question":{"hi":"'आस्तिक' का विलोम शब्द है:"},"options":[{"key":"A","hi":"नास्तिक"},{"key":"B","hi":"अनास्तिक"},{"key":"C","hi":"अस्तिक"},{"key":"D","hi":"परास्तिक"}],"answer":"A","explanation":{"hi":"आस्तिक = ईश्वर में विश्वास रखने वाला; इसका विलोम 'नास्तिक' = ईश्वर में विश्वास न रखने वाला।"}},"HIN-0004":{"id":"HIN-0004","section":"LANG1","language":"HI","topic":"समास","question":{"hi":"'नीलकंठ' में कौन-सा समास है?"},"options":[{"key":"A","hi":"द्वंद्व समास"},{"key":"B","hi":"बहुव्रीहि समास"},{"key":"C","hi":"द्विगु समास"},{"key":"D","hi":"अव्ययीभाव समास"}],"answer":"B","explanation":{"hi":"नीलकंठ = नीला है कंठ जिसका, अर्थात् शिव। जब दोनों पद मिलकर किसी तीसरे (अन्य) अर्थ की ओर संकेत करें तो बहुव्रीहि समास होता है। (केवल 'नीला कंठ' अर्थ लेने पर कर्मधारय होता है, पर विकल्पों में बहुव्रीहि ही सही है।)"}},"HIN-0005":{"id":"HIN-0005","section":"LANG1","language":"HI","topic":"संज्ञा","question":{"hi":"'बचपन' किस प्रकार की संज्ञा है?"},"options":[{"key":"A","hi":"व्यक्तिवाचक संज्ञा"},{"key":"B","hi":"जातिवाचक संज्ञा"},{"key":"C","hi":"भाववाचक संज्ञा"},{"key":"D","hi":"द्रव्यवाचक संज्ञा"}],"answer":"C","explanation":{"hi":"'बचपन' एक अवस्था/भाव है जिसे देखा या छुआ नहीं जा सकता, केवल अनुभव किया जा सकता है; इसलिए यह भाववाचक संज्ञा है (बच्चा → बचपन)।"}},"HIN-0006":{"id":"HIN-0006","section":"LANG1","language":"HI","topic":"मुहावरे","question":{"hi":"'आँखों का तारा' मुहावरे का अर्थ है:"},"options":[{"key":"A","hi":"बहुत प्यारा"},{"key":"B","hi":"आँख में चोट लगना"},{"key":"C","hi":"बहुत चालाक"},{"key":"D","hi":"रात में जागना"}],"answer":"A","explanation":{"hi":"'आँखों का तारा' का अर्थ है अत्यंत प्रिय। उदाहरण: इकलौता बेटा माँ की आँखों का तारा है।"}},"HIN-0007":{"id":"HIN-0007","section":"LANG1","language":"HI","topic":"भाषा शिक्षण","question":{"hi":"भाषा सीखने के चार कौशलों का सही क्रम है:"},"options":[{"key":"A","hi":"पढ़ना, लिखना, सुनना, बोलना"},{"key":"B","hi":"सुनना, बोलना, पढ़ना, लिखना"},{"key":"C","hi":"बोलना, सुनना, लिखना, पढ़ना"},{"key":"D","hi":"लिखना, पढ़ना, बोलना, सुनना"}],"answer":"B","explanation":{"hi":"बच्चा स्वाभाविक रूप से पहले सुनता है, फिर बोलता है, उसके बाद पढ़ना और अंत में लिखना सीखता है — LSRW (Listening, Speaking, Reading, Writing) क्रम।"}},"HIN-0008":{"id":"HIN-0008","section":"LANG1","language":"HI","topic":"वर्तनी","question":{"hi":"निम्नलिखित में से शुद्ध वर्तनी वाला शब्द है:"},"options":[{"key":"A","hi":"आशिर्वाद"},{"key":"B","hi":"आर्शीवाद"},{"key":"C","hi":"आशीर्वाद"},{"key":"D","hi":"आशीरवाद"}],"answer":"C","explanation":{"hi":"शुद्ध शब्द 'आशीर्वाद' है (आशीः + वाद)। इसमें 'शी' दीर्घ ई की मात्रा के साथ और 'र्' रेफ के रूप में 'वा' पर लगता है।"}},"KHO-0001":{"id":"KHO-0001","section":"LANG2","language":"KHO","topic":"खोरठा भाषा परिचय","question":{"hi":"खोरठा भाषा सामान्यतः किस लिपि में लिखी जाती है?"},"options":[{"key":"A","hi":"ओल चिकी"},{"key":"B","hi":"देवनागरी"},{"key":"C","hi":"बांग्ला"},{"key":"D","hi":"रोमन"}],"answer":"B","explanation":{"hi":"खोरठा साहित्य और पाठ्यपुस्तकें सामान्यतः देवनागरी लिपि में लिखी जाती हैं। ओल चिकी संथाली भाषा की लिपि है।"}},"KHO-0002":{"id":"KHO-0002","section":"LANG2","language":"KHO","topic":"खोरठा भाषा परिचय","question":{"hi":"खोरठा भाषा किस भाषा-परिवार से संबंधित है?"},"options":[{"key":"A","hi":"द्रविड़"},{"key":"B","hi":"ऑस्ट्रो-एशियाटिक (मुंडा)"},{"key":"C","hi":"भारोपीय (इंडो-आर्यन)"},{"key":"D","hi":"चीनी-तिब्बती"}],"answer":"C","explanation":{"hi":"खोरठा पूर्वी इंडो-आर्यन (भारोपीय परिवार) की भाषा है। कुड़ुख द्रविड़ परिवार की तथा संथाली, मुंडारी, हो ऑस्ट्रो-एशियाटिक (मुंडा) परिवार की भाषाएँ हैं।"}},"KHO-0003":{"id":"KHO-0003","section":"LANG2","language":"KHO","topic":"खोरठा भाषा परिचय","question":{"hi":"झारखंड के किस क्षेत्र में खोरठा मुख्य रूप से बोली जाती है?"},"options":[{"key":"A","hi":"उत्तरी छोटानागपुर एवं संथाल परगना"},{"key":"B","hi":"केवल कोल्हान प्रमंडल"},{"key":"C","hi":"केवल पलामू प्रमंडल"},{"key":"D","hi":"झारखंड के बाहर ही"}],"answer":"A","explanation":{"hi":"खोरठा मुख्यतः उत्तरी छोटानागपुर (धनबाद, बोकारो, गिरिडीह, हजारीबाग, कोडरमा, रामगढ़, चतरा आदि) तथा संथाल परगना के कई भागों में बोली जाती है।"}},"KHO-0004":{"id":"KHO-0004","section":"LANG2","language":"KHO","topic":"भाषा शिक्षण","question":{"hi":"कक्षा में खोरठा भाषी बच्चों की घरेलू भाषा के प्रति शिक्षक का सबसे उचित दृष्टिकोण है:"},"options":[{"key":"A","hi":"घरेलू भाषा बोलने पर दंड देना"},{"key":"B","hi":"घरेलू भाषा को सीखने के संसाधन के रूप में उपयोग करना"},{"key":"C","hi":"केवल मानक भाषा में ही बात करने देना"},{"key":"D","hi":"घरेलू भाषा की उपेक्षा करना"}],"answer":"B","explanation":{"hi":"NCF 2005 व NEP 2020 के अनुसार बच्चे की मातृभाषा/घरेलू भाषा सीखने का संसाधन है। बहुभाषिकता को कक्षा में सम्मान व उपयोग देने से बच्चे का आत्मविश्वास और समझ दोनों बढ़ते हैं।"}},"KHO-0005":{"id":"KHO-0005","section":"LANG2","language":"KHO","topic":"भाषा शिक्षण","question":{"hi":"NEP 2020 के अनुसार कम से कम कक्षा 5 तक (संभव हो तो कक्षा 8 तक) शिक्षण का माध्यम होना चाहिए:"},"options":[{"key":"A","hi":"केवल अंग्रेज़ी"},{"key":"B","hi":"मातृभाषा / घरेलू भाषा / स्थानीय भाषा"},{"key":"C","hi":"केवल संस्कृत"},{"key":"D","hi":"कोई विदेशी भाषा"}],"answer":"B","explanation":{"hi":"NEP 2020 कहती है कि जहाँ तक संभव हो, कम से कम कक्षा 5 तक और अधिमानतः कक्षा 8 तक शिक्षण का माध्यम मातृभाषा/घरेलू भाषा/स्थानीय या क्षेत्रीय भाषा हो। खोरठा जैसी क्षेत्रीय भाषाएँ इसी उद्देश्य से पढ़ाई जाती हैं।"}},"MS-0001":{"id":"MS-0001","section":"MATH_SCI","language":null,"topic":"LCM & HCF","question":{"en":"What is the LCM of 12 and 18?","hi":"12 और 18 का लघुत्तम समापवर्त्य (LCM) क्या है?"},"options":[{"key":"A","en":"24","hi":"24"},{"key":"B","en":"36","hi":"36"},{"key":"C","en":"54","hi":"54"},{"key":"D","en":"72","hi":"72"}],"answer":"B","explanation":{"en":"12 = 2² × 3 and 18 = 2 × 3². LCM takes the highest power of each prime: 2² × 3² = 36. 24 is not divisible by 18, so A is wrong.","hi":"12 = 2² × 3 तथा 18 = 2 × 3²। LCM में प्रत्येक अभाज्य की सबसे बड़ी घात ली जाती है: 2² × 3² = 36।"}},"MS-0002":{"id":"MS-0002","section":"MATH_SCI","language":null,"topic":"Fractions","question":{"en":"What is 3/4 + 5/6?","hi":"3/4 + 5/6 का मान क्या है?"},"options":[{"key":"A","en":"8/10","hi":"8/10"},{"key":"B","en":"19/12","hi":"19/12"},{"key":"C","en":"15/24","hi":"15/24"},{"key":"D","en":"17/12","hi":"17/12"}],"answer":"B","explanation":{"en":"LCM of 4 and 6 is 12. 3/4 = 9/12 and 5/6 = 10/12. Sum = 19/12. Option A wrongly adds numerators and denominators directly.","hi":"4 और 6 का LCM 12 है। 3/4 = 9/12 तथा 5/6 = 10/12। योग = 19/12। विकल्प A में अंश और हर सीधे जोड़ दिए गए हैं, जो गलत है।"}},"MS-0003":{"id":"MS-0003","section":"MATH_SCI","language":null,"topic":"Algebra","question":{"en":"If 3x − 7 = 11, then x = ?","hi":"यदि 3x − 7 = 11 है, तो x = ?"},"options":[{"key":"A","en":"4","hi":"4"},{"key":"B","en":"5","hi":"5"},{"key":"C","en":"6","hi":"6"},{"key":"D","en":"18","hi":"18"}],"answer":"C","explanation":{"en":"3x − 7 = 11 → 3x = 18 → x = 6. Check: 3 × 6 − 7 = 11 ✓.","hi":"3x − 7 = 11 → 3x = 18 → x = 6। जाँच: 3 × 6 − 7 = 11 ✓।"}},"MS-0004":{"id":"MS-0004","section":"MATH_SCI","language":null,"topic":"Mensuration","question":{"en":"The area of a circle is 154 cm². What is its radius? (π = 22/7)","hi":"एक वृत्त का क्षेत्रफल 154 सेमी² है। इसकी त्रिज्या क्या है? (π = 22/7)"},"options":[{"key":"A","en":"7 cm","hi":"7 सेमी"},{"key":"B","en":"14 cm","hi":"14 सेमी"},{"key":"C","en":"11 cm","hi":"11 सेमी"},{"key":"D","en":"49 cm","hi":"49 सेमी"}],"answer":"A","explanation":{"en":"πr² = 154 → (22/7) r² = 154 → r² = 154 × 7 / 22 = 49 → r = 7 cm. Option D (49) is r², not r.","hi":"πr² = 154 → (22/7) r² = 154 → r² = 154 × 7 / 22 = 49 → r = 7 सेमी। विकल्प D (49) r² है, r नहीं।"}},"MS-0005":{"id":"MS-0005","section":"MATH_SCI","language":null,"topic":"Geometry","question":{"en":"Two angles of a triangle are 50° and 60°. The third angle is:","hi":"एक त्रिभुज के दो कोण 50° और 60° हैं। तीसरा कोण है:"},"options":[{"key":"A","en":"60°","hi":"60°"},{"key":"B","en":"70°","hi":"70°"},{"key":"C","en":"80°","hi":"80°"},{"key":"D","en":"90°","hi":"90°"}],"answer":"B","explanation":{"en":"Angle sum of a triangle = 180°. Third angle = 180° − (50° + 60°) = 70°.","hi":"त्रिभुज के कोणों का योग = 180°। तीसरा कोण = 180° − (50° + 60°) = 70°।"}},"MS-0006":{"id":"MS-0006","section":"MATH_SCI","language":null,"topic":"Percentage","question":{"en":"What is 15% of 240?","hi":"240 का 15% कितना है?"},"options":[{"key":"A","en":"32","hi":"32"},{"key":"B","en":"36","hi":"36"},{"key":"C","en":"40","hi":"40"},{"key":"D","en":"24","hi":"24"}],"answer":"B","explanation":{"en":"15% of 240 = (15/100) × 240 = 36. Shortcut: 10% = 24, 5% = 12, total 36.","hi":"240 का 15% = (15/100) × 240 = 36। शॉर्टकट: 10% = 24, 5% = 12, कुल 36।"}},"MS-0007":{"id":"MS-0007","section":"MATH_SCI","language":null,"topic":"Light","question":{"en":"The image formed by a plane mirror is:","hi":"समतल दर्पण द्वारा बना प्रतिबिंब होता है:"},"options":[{"key":"A","en":"Real and inverted","hi":"वास्तविक और उल्टा"},{"key":"B","en":"Virtual and erect","hi":"आभासी और सीधा"},{"key":"C","en":"Real and erect","hi":"वास्तविक और सीधा"},{"key":"D","en":"Virtual and magnified","hi":"आभासी और आवर्धित"}],"answer":"B","explanation":{"en":"A plane mirror forms a virtual, erect image of the same size as the object, as far behind the mirror as the object is in front, and laterally inverted. It is not magnified.","hi":"समतल दर्पण आभासी, सीधा तथा वस्तु के समान आकार का प्रतिबिंब बनाता है, जो दर्पण के पीछे उतनी ही दूरी पर होता है और पार्श्व-उल्टा होता है। यह आवर्धित नहीं होता।"}},"MS-0008":{"id":"MS-0008","section":"MATH_SCI","language":null,"topic":"Living world","question":{"en":"Which part of the cell is called the 'powerhouse of the cell'?","hi":"कोशिका के किस भाग को 'कोशिका का शक्ति-गृह' कहा जाता है?"},"options":[{"key":"A","en":"Nucleus","hi":"केंद्रक"},{"key":"B","en":"Ribosome","hi":"राइबोसोम"},{"key":"C","en":"Mitochondria","hi":"माइटोकॉन्ड्रिया"},{"key":"D","en":"Golgi body","hi":"गॉल्जी काय"}],"answer":"C","explanation":{"en":"Mitochondria carry out cellular respiration and release energy as ATP, hence 'powerhouse'. The nucleus controls cell activities; ribosomes make proteins; Golgi bodies package and transport materials.","hi":"माइटोकॉन्ड्रिया कोशिकीय श्वसन द्वारा ATP के रूप में ऊर्जा मुक्त करते हैं, इसलिए 'शक्ति-गृह' कहलाते हैं। केंद्रक नियंत्रण करता है, राइबोसोम प्रोटीन बनाते हैं, गॉल्जी काय पदार्थों का पैकेजिंग करती है।"}},"MS-0009":{"id":"MS-0009","section":"MATH_SCI","language":null,"topic":"Matter","question":{"en":"Which of the following is a chemical change?","hi":"निम्नलिखित में से कौन-सा रासायनिक परिवर्तन है?"},"options":[{"key":"A","en":"Melting of ice","hi":"बर्फ का पिघलना"},{"key":"B","en":"Dissolving sugar in water","hi":"पानी में चीनी घुलना"},{"key":"C","en":"Rusting of iron","hi":"लोहे में जंग लगना"},{"key":"D","en":"Tearing of paper","hi":"कागज़ का फटना"}],"answer":"C","explanation":{"en":"Rusting forms a new substance (hydrated iron oxide) from iron, oxygen and water, and cannot be reversed easily — a chemical change. Melting, dissolving and tearing change only form/state, so they are physical changes.","hi":"जंग लगने में लोहा, ऑक्सीजन व जल से नया पदार्थ (जलयोजित आयरन ऑक्साइड) बनता है, जो सरलता से उलटा नहीं होता — यह रासायनिक परिवर्तन है। पिघलना, घुलना, फटना केवल भौतिक परिवर्तन हैं।"}},"MS-0010":{"id":"MS-0010","section":"MATH_SCI","language":null,"topic":"Electricity","question":{"en":"A current of 2 A flows through a resistor of 5 Ω. The potential difference across it is:","hi":"5 Ω के प्रतिरोधक में 2 A धारा प्रवाहित होती है। इसके सिरों के बीच विभवांतर है:"},"options":[{"key":"A","en":"2.5 V","hi":"2.5 V"},{"key":"B","en":"7 V","hi":"7 V"},{"key":"C","en":"10 V","hi":"10 V"},{"key":"D","en":"0.4 V","hi":"0.4 V"}],"answer":"C","explanation":{"en":"Ohm's law: V = I × R = 2 × 5 = 10 V. Option A divides R by I and D divides I by R, both incorrect.","hi":"ओम का नियम: V = I × R = 2 × 5 = 10 V। विकल्प A व D में गलत भाग किया गया है।"}},"MS-0011":{"id":"MS-0011","section":"MATH_SCI","language":null,"topic":"Maths pedagogy","question":{"en":"The most effective way to introduce the concept of fractions in Class 6 is:","hi":"कक्षा 6 में भिन्न की अवधारणा प्रस्तुत करने का सबसे प्रभावी तरीका है:"},"options":[{"key":"A","en":"Making students memorise the definition","hi":"विद्यार्थियों को परिभाषा रटवाना"},{"key":"B","en":"Using paper folding and sharing of real objects","hi":"कागज़ मोड़ने व वास्तविक वस्तुओं के बँटवारे का उपयोग"},{"key":"C","en":"Giving many exercises from the textbook","hi":"पाठ्यपुस्तक से ढेर सारे अभ्यास देना"},{"key":"D","en":"Starting directly with fraction rules","hi":"सीधे भिन्न के नियमों से शुरू करना"}],"answer":"B","explanation":{"en":"Maths learning should move from concrete → pictorial → abstract. Paper folding and sharing real objects build an intuitive meaning of 'part of a whole' before symbols and rules are introduced.","hi":"गणित सीखना मूर्त → चित्रात्मक → अमूर्त क्रम में होना चाहिए। कागज़ मोड़ना और वस्तुएँ बाँटना प्रतीकों व नियमों से पहले 'पूर्ण का भाग' की सहज समझ बनाते हैं।"}},"MS-0012":{"id":"MS-0012","section":"MATH_SCI","language":null,"topic":"Natural resources","question":{"en":"Which gas is mainly responsible for the greenhouse effect?","hi":"हरितगृह प्रभाव के लिए मुख्य रूप से कौन-सी गैस उत्तरदायी है?"},"options":[{"key":"A","en":"Oxygen","hi":"ऑक्सीजन"},{"key":"B","en":"Nitrogen","hi":"नाइट्रोजन"},{"key":"C","en":"Carbon dioxide","hi":"कार्बन डाइऑक्साइड"},{"key":"D","en":"Hydrogen","hi":"हाइड्रोजन"}],"answer":"C","explanation":{"en":"Carbon dioxide traps infrared radiation (heat) from the Earth's surface, warming the atmosphere. Oxygen and nitrogen, the main gases of air, do not absorb infrared significantly.","hi":"कार्बन डाइऑक्साइड पृथ्वी की सतह से निकलने वाले अवरक्त विकिरण (ऊष्मा) को रोक लेती है, जिससे वायुमंडल गर्म होता है। ऑक्सीजन व नाइट्रोजन अवरक्त विकिरण को विशेष रूप से अवशोषित नहीं करतीं।"}}},"tests":[{"id":1,"slug":"full-1","title":"Full Mock 1","type":"FULL","sectionId":null,"duration":150,"total":45,"questionIds":["CDP-0001","CDP-0002","CDP-0003","CDP-0004","CDP-0005","CDP-0006","CDP-0007","CDP-0008","CDP-0009","CDP-0010","MS-0001","MS-0002","MS-0003","MS-0004","MS-0005","MS-0006","MS-0007","MS-0008","MS-0009","MS-0010","MS-0011","MS-0012","COMP-0001","COMP-0002","COMP-0003","COMP-0004","COMP-0005","COMP-0006","COMP-0007","COMP-0008","COMP-0009","COMP-0010","ENG-0001","ENG-0002","ENG-0003","ENG-0004","ENG-0005","ENG-0006","ENG-0007","ENG-0008","HIN-0001","HIN-0002","HIN-0003","HIN-0004","HIN-0005","HIN-0006","HIN-0007","HIN-0008","KHO-0001","KHO-0002","KHO-0003","KHO-0004","KHO-0005"]},{"id":2,"slug":"sec-cdp-1","title":"Child Development & Pedagogy — Practice Test 1","type":"SECTIONAL","sectionId":"CDP","duration":10,"total":10,"questionIds":["CDP-0001","CDP-0002","CDP-0003","CDP-0004","CDP-0005","CDP-0006","CDP-0007","CDP-0008","CDP-0009","CDP-0010"]},{"id":3,"slug":"sec-math_sci-1","title":"Mathematics & Science — Practice Test 1","type":"SECTIONAL","sectionId":"MATH_SCI","duration":12,"total":12,"questionIds":["MS-0001","MS-0002","MS-0003","MS-0004","MS-0005","MS-0006","MS-0007","MS-0008","MS-0009","MS-0010","MS-0011","MS-0012"]},{"id":4,"slug":"sec-computer-1","title":"Computer — Practice Test 1","type":"SECTIONAL","sectionId":"COMPUTER","duration":10,"total":10,"questionIds":["COMP-0001","COMP-0002","COMP-0003","COMP-0004","COMP-0005","COMP-0006","COMP-0007","COMP-0008","COMP-0009","COMP-0010"]},{"id":5,"slug":"sec-lang1-1","title":"Language-1 (English / Hindi) — Practice Test 1","type":"SECTIONAL","sectionId":"LANG1","duration":8,"total":8,"questionIds":["ENG-0001","ENG-0002","ENG-0003","ENG-0004","ENG-0005","ENG-0006","ENG-0007","ENG-0008","HIN-0001","HIN-0002","HIN-0003","HIN-0004","HIN-0005","HIN-0006","HIN-0007","HIN-0008"]},{"id":6,"slug":"sec-lang2-1","title":"Language-2 (Khortha) — Practice Test 1","type":"SECTIONAL","sectionId":"LANG2","duration":5,"total":5,"questionIds":["KHO-0001","KHO-0002","KHO-0003","KHO-0004","KHO-0005"]}]};
